import Link from "next/link";
import type { ReactNode } from "react";

import { speakerMessage } from "@/lib/passages";
import type { Passage } from "@/lib/types";

import { T } from "./i18n/T";
import { Icon } from "./Icon";
import { Label } from "./Label";
import { Ornament } from "./Ornament";
import { ProvenanceBadge } from "./ProvenanceBadge";
import { VerseActions } from "./VerseActions";

/**
 * A passage exactly as stored in the verified corpus: original text,
 * transliteration, translation with attribution, and links to check it.
 * Nothing here is generated by a model. Below it, the same few actions
 * everywhere: copy, share, save, and ask about it.
 *
 * "feature" sets one passage as a plate, for the verse page; "plain" is an
 * open entry for lists, separated by the list's own dividers; "reading" is
 * the larger open entry of an answer's reading column, opened by a fine rule
 * and numbered in the margin.
 *
 * The reading preferences (lib/reading.ts) size the text and can hide the
 * Sanskrit or the transliteration, through the classes on them.
 */
export function VerseCard({
  passage,
  variant = "feature",
  headingLevel = 3,
  showVerseLink = true,
  compact = false,
  number,
  id,
  annotation,
  actions = true,
}: {
  passage: Passage;
  variant?: "feature" | "plain" | "reading";
  headingLevel?: 1 | 2 | 3 | 4;
  showVerseLink?: boolean;
  compact?: boolean;
  /** "reading" only: the passage's place in the answer. */
  number?: number;
  id?: string;
  /** A line under the heading, such as why search found it. */
  annotation?: ReactNode;
  /** Copy, share, save and ask about this passage. */
  actions?: boolean;
}) {
  const Heading = `h${headingLevel}` as const;
  const feature = variant === "feature";
  const reading = variant === "reading";
  const who = speakerMessage(passage);
  const speaker = who && <T k={who.key} values={who.values} />;
  const place = passage.source_id === "bhagavad-gita" && passage.chapter_title ? (
    <T k="verse.chapterTitle" values={{ chapter: passage.chapter ?? "", title: passage.chapter_title }} />
  ) : (
    passage.chapter_title
  );
  const showNotes = !compact && (passage.translator_notes.length > 0 || passage.context_notes.length > 0);

  const reference = showVerseLink ? (
    <Link href={passage.path} className="decoration-gold/60 underline-offset-[5px] transition-colors hover:underline">
      {passage.ref}
    </Link>
  ) : (
    passage.ref
  );

  return (
    <article
      id={id}
      aria-label={passage.ref}
      className={
        feature
          ? "relative overflow-hidden rounded-[1.75rem] bg-source-bg px-4 pt-6 pb-5 ring-1 ring-rule sm:px-10 sm:pt-8 sm:pb-8"
          : reading
            ? "relative scroll-mt-36 border-t border-rule-strong pt-8 pb-12"
            : "relative py-7"
      }
    >
      {reading && number !== undefined && (
        <span
          aria-hidden
          className="absolute top-7 -left-28 hidden w-20 text-right font-serif text-[2.25rem] leading-none text-gold tabular-nums xl:block"
        >
          {String(number).padStart(2, "0")}
        </span>
      )}
      {feature && (
        // A fine inner frame, like the ruled border of a manuscript leaf; closer to the edge on phones.
        <span
          aria-hidden
          className="pointer-events-none absolute inset-1 rounded-[1.5rem] border border-gold/20 sm:inset-2 sm:rounded-[1.375rem] sm:border-gold/25"
        />
      )}

      <header className="relative flex flex-wrap items-start justify-between gap-x-4 gap-y-2">
        <div className="min-w-0">
          <Label kind="source" />
          <Heading
            className={
              feature
                ? `display mt-3 text-ink ${headingLevel === 1 ? "text-[2rem] sm:text-[2.5rem]" : "text-[1.75rem]"} leading-tight`
                : reading
                  ? "display mt-3 text-[1.875rem] leading-tight text-ink sm:text-[2.125rem]"
                  : "mt-2.5 text-[1.0625rem] font-semibold tracking-tight text-ink"
            }
          >
            {reference}
          </Heading>
          {(speaker || place) && (
            <p className="mt-1 text-[0.8125rem] text-ink-muted">
              {speaker}
              {speaker && place && " · "}
              {place}
            </p>
          )}
          {annotation}
        </div>
        <ProvenanceBadge provenance={passage.provenance} />
      </header>

      {passage.sanskrit && (
        <p
          lang="sa"
          className={`verse-sanskrit deva relative text-ink ${
            feature
              ? "verse-centred mt-7 text-center text-[calc(1.25rem*var(--reading-scale))] sm:mt-8 sm:text-[calc(1.625rem*var(--reading-scale))]"
              : reading
                ? "mt-7 text-[calc(1.1875rem*var(--reading-scale))] sm:text-[calc(1.5rem*var(--reading-scale))]"
                : compact
                  ? "mt-4 text-[calc(1.125rem*var(--reading-scale))]"
                  : "mt-5 text-[calc(1.25rem*var(--reading-scale))]"
          }`}
        >
          <VerseLines text={passage.sanskrit} />
        </p>
      )}
      {passage.transliteration && !compact && (
        <p
          lang="sa-Latn"
          className={`verse-transliteration relative font-serif text-[calc(0.9375rem*var(--reading-scale))] leading-relaxed text-ink-muted italic ${
            feature ? "verse-centred mt-3 text-center" : "mt-2"
          }`}
        >
          <VerseLines text={passage.transliteration} />
        </p>
      )}
      {feature && passage.sanskrit && <Ornament className="verse-ornament relative mx-auto mt-8 w-28 text-gold/70" />}

      <blockquote
        className={`relative font-serif text-pretty text-ink ${
          feature
            ? "mt-7 text-[calc(1.1875rem*var(--reading-scale))] leading-[1.75] sm:text-[calc(1.3125rem*var(--reading-scale))]"
            : reading
              ? "mt-6 text-[calc(1.1875rem*var(--reading-scale))] leading-[1.75] sm:text-[calc(1.3125rem*var(--reading-scale))]"
              : passage.sanskrit
                ? "mt-3 text-[calc(1.0625rem*var(--reading-scale))] leading-[1.75]"
                : "mt-4 text-[calc(1.0625rem*var(--reading-scale))] leading-[1.75]"
        }`}
      >
        {passage.translation}
      </blockquote>

      <footer
        className={`relative flex flex-wrap items-center gap-x-5 gap-y-2 text-[0.8125rem] text-ink-muted ${
          feature ? "mt-7 border-t border-gold/20 pt-4" : reading ? "mt-6" : "mt-4"
        }`}
      >
        <span>
          <T k="verse.translatedBy" values={{ translator: <span className="text-ink-soft">{passage.translator}</span> }} />
        </span>
        <a
          href={passage.citation.scan_url ?? passage.citation.url}
          target="_blank"
          rel="noreferrer"
          className="font-medium text-ink-soft underline decoration-rule-strong underline-offset-[3px] transition-colors hover:text-ink hover:decoration-accent"
          title={passage.citation.label}
        >
          {passage.citation.scan_url ? (
            passage.citation.page ? (
              <T k="verse.printedPage" values={{ page: passage.citation.page }} />
            ) : (
              <T k="verse.printedPageAlone" />
            )
          ) : (
            <T k="verse.sourceText" />
          )}{" "}
          ↗
        </a>
        {showVerseLink && (
          <Link
            href={passage.path}
            className="group inline-flex items-center gap-1 font-medium text-ink-soft transition-colors hover:text-ink sm:ml-auto"
          >
            <T k="verse.details" />
            <Icon name="arrowRight" className="size-3.5 transition-transform group-hover:translate-x-0.5" />
          </Link>
        )}
      </footer>

      {actions && (
        <div className={`relative ${feature ? "mt-4" : "mt-3"}`}>
          <VerseActions passage={passage} size={variant === "plain" ? "compact" : "full"} />
        </div>
      )}

      {showNotes && (
        <div className="relative mt-5 space-y-3 text-sm">
          {passage.translator_notes.length > 0 && (
            <details className="group rounded-xl bg-surface/70 px-4 py-3 ring-1 ring-rule">
              <summary className="flex items-center gap-2 font-medium text-ink-soft transition-colors hover:text-ink">
                <Icon name="chevronRight" className="size-4 transition-transform group-open:rotate-90" />
                <T k="verse.notes" values={{ count: passage.translator_notes.length }} />
              </summary>
              <div className="mt-3 pl-6">
                <Label kind="note" />
                <ul className="mt-2 space-y-2 font-serif text-[calc(0.9375rem*var(--reading-scale))] leading-relaxed text-ink-soft">
                  {passage.translator_notes.map((note, i) => (
                    <li key={i}>
                      {note.anchor && <span className="font-semibold text-ink">{note.anchor}: </span>}
                      {note.text}
                    </li>
                  ))}
                </ul>
              </div>
            </details>
          )}
          {passage.context_notes.length > 0 && (
            <div className="flex flex-wrap items-baseline gap-x-3 gap-y-1.5 rounded-xl bg-editorial-bg px-4 py-3">
              <Label kind="editorial">
                <T k="verse.contextNote" />
              </Label>
              <p className="min-w-0 flex-1 leading-relaxed text-ink-soft">{passage.context_notes.join(" ")}</p>
            </div>
          )}
        </div>
      )}
    </article>
  );
}

/**
 * The lines of a verse as printed: each half-verse its own line. When one is
 * too long for the screen it wraps into balanced halves, and the continuation
 * is indented, so it still reads as one half-verse; the text itself is never
 * changed. A verse-number marker such as “॥ ४७ ॥” or “|| 47 ||” never breaks
 * across lines, and a half-verse mark (। or |) stays on the line of the word
 * before it.
 */
export function VerseLines({ text }: { text: string }) {
  const lines = text.split("\n");
  return (
    <>
      {lines.map((line, i) => (
        <span key={i} className="verse-line">
          <VerseLine text={line} />
        </span>
      ))}
    </>
  );
}

function VerseLine({ text: raw }: { text: string }) {
  const text = raw.replace(/[ \t]+([।|])(?=[ \t]*$)/, " $1");
  const match = /(\s*(?:॥|\|\|)\s*[\d०-९]+\s*(?:॥|\|\|))\s*$/.exec(text);
  if (!match) return <>{text}</>;
  return (
    <>
      {text.slice(0, match.index)}
      <span className="whitespace-nowrap">{match[1]}</span>
    </>
  );
}
